import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import {
  addressFromPrivateKey, addressToBytes, bytesToHex, deriveKey, formatLyx, hexToBytes,
  isAddress, isMnemonic, parseLyx, signOp, signingHash, minTransferFee, encodeOp, minFee,
  signTransfer, signSwap, signVault, signPqCommit, signRotate, signCancelRotate,
  SWAP_ADDRESS, VAULT_ADDRESS, KEY_ADDRESS, DEPLOY_ADDRESS, TIMELOCK_ADDRESS, TOKEN_ADDRESS,
  type Op, type TxFields,
} from './lokyx';

// Generated by the Rust node: `cargo run --example vectors > testdata/vectors.json`
const v = JSON.parse(readFileSync(new URL('../../../testdata/vectors.json', import.meta.url), 'utf8'));

const h = (x: string) => hexToBytes(x);
const settings = (s: any) => ({
  recovery: s.recovery, safe: s.safe, delay: BigInt(s.delay), allowance: BigInt(s.allowance),
  heir: s.heir ? { address: s.heir.address, inactiveBlocks: BigInt(s.heir.inactiveBlocks) } : null,
});

/** The op of a vector case, as the library's Op. */
function opOf(o: any): Op {
  switch (o.kind) {
    case 'transfer': return { kind: 'transfer', to: o.to, value: BigInt(o.value) };
    case 'batch': return { kind: 'batch', payments: o.payments.map((p: any) => ({ to: p.to, amount: BigInt(p.amount) })) };
    case 'swapLock': return { kind: 'swapLock', amount: BigInt(o.amount), hashlock: h(o.hashlock), recipient: o.recipient, refundHeight: BigInt(o.refundHeight) };
    case 'swapClaim': return { kind: 'swapClaim', lock: h(o.lock), secret: h(o.secret) };
    case 'swapRefund': return { kind: 'swapRefund', lock: h(o.lock) };
    case 'vaultCreate': return { kind: 'vaultCreate', settings: settings(o.settings) };
    case 'vaultUpdate': return { kind: 'vaultUpdate', settings: settings(o.settings) };
    case 'vaultWithdraw': return { kind: 'vaultWithdraw', to: o.to, amount: BigInt(o.amount) };
    case 'vaultClose': return { kind: 'vaultClose' };
    case 'vaultCancel': return { kind: 'vaultCancel', id: h(o.id) };
    case 'vaultSweep': return { kind: 'vaultSweep', vault: o.vault };
    case 'vaultHeirClaim': return { kind: 'vaultHeirClaim', vault: o.vault };
    case 'keyCommitPq': return { kind: 'keyCommitPq', hash: h(o.hash) };
    case 'keyRotate': return { kind: 'keyRotate', newKey: o.newKey };
    case 'keyCancelRotate': return { kind: 'keyCancelRotate', account: o.account };
    case 'timelockLock': return { kind: 'timelockLock', beneficiary: o.beneficiary, amount: BigInt(o.amount), unlockHeight: BigInt(o.unlockHeight) };
    case 'timelockClaim': return { kind: 'timelockClaim', id: h(o.id) };
    case 'tokenCreate': return { kind: 'tokenCreate', symbol: o.symbol, name: o.name, decimals: o.decimals, supply: BigInt(o.supply) };
    case 'tokenTransfer': return { kind: 'tokenTransfer', token: h(o.token), to: o.to, amount: BigInt(o.amount) };
    case 'tokenBurn': return { kind: 'tokenBurn', token: h(o.token), amount: BigInt(o.amount) };
    case 'deploy': return { kind: 'deploy', value: BigInt(o.value), code: h(o.code), abi: o.abi, input: h(o.input), gas: BigInt(o.gas) };
    case 'call': return { kind: 'call', to: o.to, value: BigInt(o.value), input: h(o.input), gas: BigInt(o.gas) };
  }
  throw new Error(`unknown vector op ${o.kind}`);
}

const fieldsOf = (t: any): TxFields & { from: string; fee: bigint } => ({
  chainId: BigInt(t.chainId), from: t.from, nonce: BigInt(t.nonce), expires: BigInt(t.expires),
  memo: h(t.memo), fee: BigInt(t.fee),
});

describe('matches the node', () => {
  it('derives the same keys and addresses', () => {
    for (const k of v.keys) {
      const sk = deriveKey(v.mnemonic, k.index);
      expect(bytesToHex(sk)).toBe(k.privateKey);
      expect(addressFromPrivateKey(sk)).toBe(k.address);
      expect('0x' + bytesToHex(addressToBytes(k.address))).toBe(k.evm);
    }
    const one = new Uint8Array(32);
    one[31] = 1;
    expect(addressFromPrivateKey(one)).toBe(v.privkeyOneAddress);
  });

  it('uses the same system addresses', () => {
    expect(SWAP_ADDRESS).toBe(v.addresses.swap);
    expect(VAULT_ADDRESS).toBe(v.addresses.vault);
    expect(KEY_ADDRESS).toBe(v.addresses.key);
    expect(DEPLOY_ADDRESS).toBe(v.addresses.deploy);
    expect(TIMELOCK_ADDRESS).toBe(v.addresses.timelock);
    expect(TOKEN_ADDRESS).toBe(v.addresses.token);
  });

  it('has a vector for every kind of operation', () => {
    expect(v.cases.length).toBeGreaterThanOrEqual(23);
  });

  // Every case: the op bytes, the signing hash, the signed bytes and the hash, byte for byte.
  for (const c of v.cases) {
    it(`signs an identical ${c.name}`, () => {
      const sk = h(v.keys[c.key].privateKey);
      const f = fieldsOf(c.tx);
      const op = opOf(c.tx.op);
      expect(bytesToHex(encodeOp(op))).toBe(c.tx.opBytes);
      expect(bytesToHex(signingHash(f, op))).toBe(c.signingHash);
      const s = signOp(op, f, sk);
      expect(bytesToHex(s.bytes)).toBe(c.signed);
      expect(s.hash).toBe(c.hash);
    });
  }

  it('prices a transaction at its signed size (plus gas for contracts)', () => {
    for (const c of v.cases) {
      const f = fieldsOf(c.tx);
      const least = minFee({ ...f, fee: undefined }, opOf(c.tx.op));
      // one case pays more than the minimum on purpose
      if (c.name.startsWith('transfer with memo')) expect(least < BigInt(c.tx.fee)).toBe(true);
      else expect(least.toString()).toBe(c.tx.fee);
    }
    expect(minTransferFee().toString()).toBe(v.cases[0].tx.fee);
  });
});

describe('the conveniences build the same transactions', () => {
  const sk0 = h(v.keys[0].privateKey);
  const sk1 = h(v.keys[1].privateKey);
  const chainId = BigInt(v.chainId);
  const by = (name: string) => v.cases.find((c: any) => c.name === name);
  it('transfer', () => {
    const c = by('transfer');
    const s = signTransfer({ chainId, nonce: 0n, to: c.tx.op.to, value: BigInt(c.tx.op.value) }, sk0);
    expect(bytesToHex(s.bytes)).toBe(c.signed);
  });
  it('swap lock, claim and refund', () => {
    const l = by('swap lock').tx.op;
    expect(bytesToHex(signSwap({ kind: 'lock', hashlock: h(l.hashlock), recipient: l.recipient, refundHeight: BigInt(l.refundHeight) }, chainId, 3n, sk0, BigInt(l.amount)).bytes)).toBe(by('swap lock').signed);
    const cl = by('swap claim').tx.op;
    expect(bytesToHex(signSwap({ kind: 'claim', lock: h(cl.lock), secret: h(cl.secret) }, chainId, 0n, sk1).bytes)).toBe(by('swap claim').signed);
    expect(bytesToHex(signSwap({ kind: 'refund', lock: h(cl.lock) }, chainId, 4n, sk0).bytes)).toBe(by('swap refund').signed);
  });
  it('vault ops', () => {
    const o = by('vault create').tx.op;
    expect(bytesToHex(signVault({ kind: 'create', settings: settings(o.settings) }, chainId, 10n, sk0).bytes)).toBe(by('vault create').signed);
    expect(bytesToHex(signVault({ kind: 'close' }, chainId, 13n, sk0).bytes)).toBe(by('vault close').signed);
  });
  it('key ops', () => {
    expect(bytesToHex(signPqCommit(h(by('key commit').tx.op.hash), chainId, 20n, sk0).bytes)).toBe(by('key commit').signed);
    expect(bytesToHex(signRotate(by('key rotate').tx.op.newKey, { chainId, nonce: 24n }, sk0).bytes)).toBe(by('key rotate').signed);
    expect(bytesToHex(signCancelRotate(by('key cancel rotate').tx.op.account, { chainId, nonce: 25n }, sk0).bytes)).toBe(by('key cancel rotate').signed);
  });
  it('acts for another account when told to (a rotated key)', () => {
    const newKey = h(v.keys[1].privateKey);
    const s = signOp({ kind: 'transfer', to: v.keys[2].address, value: 1n }, { chainId, nonce: 5n, from: v.keys[0].address }, newKey);
    // the `from` field is the account, not the signer: the first 20 bytes after version and chain id
    expect(bytesToHex(s.bytes.slice(9, 29))).toBe(bytesToHex(addressToBytes(v.keys[0].address)));
  });
  it('refuses a long memo and an oversize batch', () => {
    expect(() => signOp({ kind: 'transfer', to: v.keys[1].address, value: 1n }, { chainId, nonce: 0n, memo: new Uint8Array(65) }, sk0)).toThrow();
    expect(() => encodeOp({ kind: 'batch', payments: [] })).toThrow();
    expect(() => encodeOp({ kind: 'batch', payments: Array.from({ length: 257 }, () => ({ to: v.keys[1].address, amount: 1n })) })).toThrow();
  });
});

describe('input handling', () => {
  it('rejects bad addresses', () => {
    const good = v.keys[0].address as string;
    expect(isAddress(good)).toBe(true);
    expect(isAddress(good.toUpperCase())).toBe(true);
    expect(isAddress(good.slice(0, -1) + (good.endsWith('q') ? 'p' : 'q'))).toBe(false);
    expect(isAddress('0x' + '00'.repeat(20))).toBe(false);
    expect(isAddress(good.slice(0, 6) + good[6].toUpperCase() + good.slice(7))).toBe(false);
  });

  it('parses and formats amounts exactly', () => {
    expect(parseLyx('1.5')).toBe(1_500_000_000_000_000_000n);
    expect(formatLyx(parseLyx('1234.000000000000000001'))).toBe('1,234.000000000000000001');
    expect(() => parseLyx('1e3')).toThrow();
    expect(() => parseLyx('-1')).toThrow();
    expect(() => parseLyx('0.0000000000000000001')).toThrow();
  });

  it('checks recovery phrases', () => {
    expect(isMnemonic('  ' + v.mnemonic.toUpperCase() + ' ')).toBe(true);
    expect(isMnemonic(v.mnemonic.replace('about', 'abandon'))).toBe(false);
  });
});

describe('post-quantum key', () => {
  it('derives a stable SLH-DSA key from the phrase', async () => {
    const { pqCommitment, pqPublicKey } = await import('./pq');
    const a = pqCommitment(v.mnemonic);
    expect(a.length).toBe(32);
    expect(bytesToHex(pqCommitment(v.mnemonic))).toBe(bytesToHex(a));
    expect(pqPublicKey(v.mnemonic).length).toBe(32);
    const other = 'legal winner thank year wave sausage worth useful legal winner thank yellow';
    expect(bytesToHex(pqCommitment(other))).not.toBe(bytesToHex(a));
  }, 60_000);
});
